    /// <summary>
    /// Finds the specified record in the <c>METSalesOrderTypes</c> table.
    /// </summary>
    /// <param name="_salesOrderTypeID">
    /// The SalesOrderTypeID of the <c>METSalesOrderTypes</c> record to find.
    /// </param>
    /// <param name="_forupdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    /// The ConcurrencyModel value set to; Auto.
    /// </param>
    /// <returns>
    /// A record in the <c>METSalesOrderTypes</c> table; otherwise, an empty record.
    /// </returns>
    public static METSalesOrderTypes find(
        METSalesOrderTypeID _salesOrderTypeID,
        boolean _forupdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METSalesOrderTypes salesOrderTypes;

        salesOrderTypes.selectForUpdate(_forupdate);
        if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
        {
            salesOrderTypes.concurrencyModel(_concurrencyModel);
        }

        select firstonly salesOrderTypes 
            where salesOrderTypes.SalesOrderTypeID == _salesOrderTypeID;

        return salesOrderTypes;
    }

    /// <summary>
    /// Finds the default record in the <c>METSalesOrderTypes</c> table.
    /// </summary>
    /// <param name="_forupdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    /// The ConcurrencyModel value set to; Auto.
    /// </param>
    /// <returns>
    /// A record in the <c>METSalesOrderTypes</c> table; otherwise, an empty record.
    /// </returns>
    public static METSalesOrderTypes findDefaultType(
        boolean _forupdate = false, 
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METSalesOrderTypes salesOrderTypes;

        salesOrderTypes.selectForUpdate(_forupdate);
        if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
        {
            salesOrderTypes.concurrencyModel(_concurrencyModel);
        }

        select firstonly salesOrderTypes 
            where salesOrderTypes.IsDefault == NoYes::Yes;

        return salesOrderTypes;
    }

    /// <summary>
    /// Exists the specified record in the <c>METSalesOrderTypes</c> table.
    /// </summary>
    /// <param name = "_salesOrderTypeID">
    /// The SalesOrderTypeID of the <c>METSalesOrderTypes</c> record to exists.
    /// </param>
    /// <returns>A Boolean value that indicates whether the record exists or not</returns>
    public static boolean exist(METSalesOrderTypeID _salesOrderTypeID)
    {
        boolean found;

        found = (select firstonly
                     RecId
                from
                     METSalesOrderTypes
                 where
                     METSalesOrderTypes.SalesOrderTypeID == _salesOrderTypeID).RecId != 0;

        return found;
    }
